// get user orders
export async function getUserOrders(
  userId: string,
): Promise<userOrdersResponce> {
  const responce = await fetch(
    `https://ecommerce.routemisr.com/api/v1/orders/user/${userId}`,
    {
      next: {
        revalidate: 60,
        tags: ["allUserOrders"],
      },
    },
  );
  const data = await responce.json();
