                          </span>
                        </div>

                        <DetailsOrderBtn id={order._id} />
                      </div>
                    </div>
                  </div>
                </div>
                <OrderDetails order={order} />
              </div>
            ))}
        </div>
      </div>
    </div>
  );
}

