  async function handleRegisterSubmit(values: any) {
    setLoading(true);
    if (paymentMethod === "cash") {
      setNumOfCartItems(0);
      const handleRegister = await handleCashOrderSubmitAction(
        values,
        cartResponce.data._id,
      );
    } else {
      setNumOfCartItems(0);
      const handleRegister = await handlecheckoutSubmitAction(
        values,
        cartResponce.data._id,
