"use client";
import { useWishlistStore } from "@/src/stores/wishlistStore.store";
import React, { useEffect, useState } from "react";
import { FaHeart, FaRegHeart } from "react-icons/fa";
import { toast } from "sonner";
import { Spinner } from "@/components/ui/spinner";

export default function AddWishlist({ productId }: { productId: string }) {
  const {
    addToWishlist,
    increaseNumOfWishlist,
    wishlist,
    deleteItemFromWishlist,
    decreaseNumOfWishlist,
  } = useWishlistStore();
  const [loading, setLoading] = useState(false);

  const inWishist =
    wishlist?.data?.some(
      (product: any) => String(product._id) === String(productId),
    ) ?? false;

  async function addToWishlistProccess() {
    if (loading) return;

    setLoading(true);
    try {
      if (inWishist) {
        const res = await deleteItemFromWishlist(productId);

        if (res.status === "success") {
          decreaseNumOfWishlist();
          toast.success(res.message);
        } else {
          toast.error("Error in removing item from your wishlist");
        }
      } else {
        const res = await addToWishlist(productId);

        if (res.status === "success") {
          increaseNumOfWishlist();
          toast.success(res.message);
        } else {
          toast.error("Error in adding item to your wishlist");
        }
      }
    } catch (error) {
      console.error(error);
      toast.error("Something went wrong");
    } finally {
      setLoading(false);
    }
  }

  return (
    <>
      <button
        disabled={loading}
        onClick={addToWishlistProccess}
        className="cursor-pointer bg-white h-8 w-8 rounded-full flex items-center justify-center transition shadow-sm text-gray-600 hover:text-red-500 disabled:opacity-70 disabled:cursor-not-allowed"
        title="Add to wishlist"
        tabIndex={0}
      >
        {loading ? (
          <Spinner className="text-red-500 w-4 h-4" />
        ) : (
          <div>
            {inWishist ? <FaHeart className="text-red-600" /> : <FaRegHeart />}
          </div>
        )}
      </button>
    </>
  );
}

import { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";

export const NextAuthConfig: NextAuthOptions = {
  providers: [
    CredentialsProvider({
      name: "FreshCart",
      credentials: {
        email: {
          label: "Email",
          type: "text",
          placeholder: "Please enter your email",
        },
        password: {
          label: "Password",
          type: "password",
          placeholder: "Please enter your password",
        },
      },
      authorize: async (credentials) => {
        const res = await fetch(
          "https://ecommerce.routemisr.com/api/v1/auth/signin",
          {
            method: "POST",
            body: JSON.stringify(credentials),
            headers: {
              "Content-Type": "application/json",
            },
          },
        );

        if (!res.ok) return null;

        const data = await res.json();

        console.log("LOGIN RESPONSE:", data);

        if (data.message === "success" && data.user) {
          return {
            id: data.user.email,
            email: data.user.email,
            name: data.user.name,
            accessToken: data.token,
          };
        }
        return null;
      },
    }),
  ],
  secret: process.env.NEXTAUTH_SECRET,
  callbacks: {
    jwt: ({ token, user }) => {
      if (user) {
        token.accessToken = (user as any).accessToken;
      }
      return token;
    },
    session: ({ session, token }) => {
      (session as any).accessToken = token.accessToken; // هنا عشان لو عايز ارجع ال token فى ال session
      return session;
    },
  },
  pages: {
    signIn: "/login",
  },
};

import { create } from "zustand";
import {
  getUserCart,
  addToCartAction,
  clearUserCart,
  deleteItemCount,
  updateItemCount,
} from "../apiDataFetching/cart/cart.actions";
import { CrudCartResponce } from "../types/cart.interface";

type CounterStore = {
  cart: CrudCartResponce | null;
  numOfCartItems: number | null;
  getUserCart: () => Promise<CrudCartResponce>;
  updateItemCount: (
    productId: string,
    count: number,
  ) => Promise<CrudCartResponce>;
  addToCart: (productId: string) => Promise<CrudCartResponce>;
  clearCart: () => Promise<CrudCartResponce>;
  deleteItemFromCart: (productId: string) => Promise<CrudCartResponce>;
  setNumOfCartItems: (count: number) => void;
  quantity: number ;
  setQuantity: (number: number) => void;
};

export const useCounterStore = create<CounterStore>((set) => ({
  cart: null,
  numOfCartItems: null,
  quantity: 1,

  setQuantity: (number) => {
    set((state) => ({
      quantity: number ,
    }));
  },

  // get user cart
  getUserCart: async () => {
    const data = await getUserCart();
    set((state) => ({
      cart: data,
      numOfCartItems: data?.numOfCartItems,
    }));
    return data;
  },
  // add to cart
  addToCart: async (productId: string) => {
    const data = await addToCartAction(productId);
    set((state) => ({
      cart: data,
      numOfCartItems: data?.numOfCartItems,
    }));
    return data;
  },
  // update cart
  updateItemCount: async (productId: string, count: number) => {
    const data = await updateItemCount(productId, count);
    set(() => ({
      cart: data,
      numOfCartItems: data?.numOfCartItems,
    }));
    return data;
  },
  // delete item from cart
  deleteItemFromCart: async (productId: string) => {
    const data = await deleteItemCount(productId);
    set((state) => ({
      cart: data,
      numOfCartItems: data?.numOfCartItems,
    }));
    return data;
  },
  // clear all cart items
  clearCart: async () => {
    const data = await clearUserCart();
    set((state) => ({
      numOfCartItems: null,
      cart: null,
    }));
    return data;
  },
  // set number of cart items
  setNumOfCartItems: (count: number) => {
    set((state) => ({
      numOfCartItems: count,
    }));
  },
}));

